from fractions import Fraction
import random


def card_sum_fair(revealed, n_cards, deck_total=364, deck_size=52):
    k = len(revealed)
    shown = sum(revealed)
    if k == n_cards:
        return Fraction(shown)
    return shown + (n_cards - k) * Fraction(deck_total - shown, deck_size - k)


def make_script(seed, n_cards=3):
    r = random.Random(seed)
    deck = [v for v in range(1, 14) for _ in range(4)]
    cards = r.sample(deck, n_cards)
    script = []
    for i, c in enumerate(cards):
        for _ in range(2):
            side = r.choice(["buy", "sell", None])
            if side:
                script.append((side, r.randint(1, 3)))
        script.append(("reveal", c))
        if i == 0:
            script.append(("hedge", Fraction(c * 10 + r.choice([-1, 1]), 10)))
    return script


def skew_rule(fair, position):
    m = Fraction(round(2 * (fair - Fraction(position, 2))), 2)
    return (m - 2, m + 2)


def centre_rule(fair, position):
    return (fair - 2, fair + 2)

