import random
import statistics


def kelly_game(p, b, f, bets, seed, bankroll=100.0):
    """Final bankroll of one seeded path: each bet stakes
    f of the bankroll, wins b per £1 if rng.random() < p,
    else loses the stake. rng = random.Random(seed)."""
    rng = random.Random(seed)
    for _ in range(bets):
        stake = f * bankroll
        if rng.random() < p:
            bankroll += b * stake
        else:
            bankroll -= stake
    return bankroll


def median_bankroll(p, b, f, bets, paths, seed, bankroll=100.0):
    """Median final bankroll over paths seeded seed,
    seed + 1, ..., seed + paths - 1."""
    finals = [kelly_game(p, b, f, bets, seed + i, bankroll)
              for i in range(paths)]
    return statistics.median(finals)
